/bin/zsh -lc "python3 -B - <<'PY'
from pathlib import Path
import difflib
for origin in ('.pre-repair', '.baseline'):
    names = ('vault.py', 'app.py', 'test_regressions.py', 'test_public.py') if origin == '.pre-repair' else ('vault.py', 'app.py', 'test_public.py')
    for name in names:
        old, new = Path(origin, name), Path(name)
        before, after = old.read_text(), new.read_text()
        if before == after:
            print(f'{old} == {new}')
        else:
            print(''.join(difflib.unified_diff(before.splitlines(True), after.splitlines(True), fromfile=str(old), tofile=str(new))), end='')
PY"

